mkdir -p /tmp/fanin && cat > /tmp/fanin/main.go <<'EOF'
package main

import (
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"sort"
	"strings"

	"golang.org/x/tools/go/packages"
)

func main() {
	cfg := &packages.Config{
		Mode: packages.NeedName | packages.NeedFiles | packages.NeedSyntax |
			packages.NeedTypes | packages.NeedTypesInfo | packages.NeedDeps | packages.NeedImports,
		Dir:   "/bench/repo",
		Tests: false,
	}
	pkgs, err := packages.Load(cfg, "./...")
	if err != nil {
		panic(err)
	}
	fset := token.NewFileSet()
	_ = fset

	type info struct {
		name  string
		pos   string
		count int
	}
	counts := map[*types.Func]int{}
	declFile := map[*types.Func]string{}

	packages.Visit(pkgs, nil, func(p *packages.Package) {
		if p.TypesInfo == nil {
			return
		}
		fs := p.Fset
		for _, f := range p.Syntax {
			ast.Inspect(f, func(n ast.Node) bool {
				call, ok := n.(*ast.CallExpr)
				if !ok {
					return true
				}
				var id *ast.Ident
				switch fun := call.Fun.(type) {
				case *ast.Ident:
					id = fun
				case *ast.SelectorExpr:
					id = fun.Sel
				default:
					return true
				}
				obj := p.TypesInfo.Uses[id]
				fn, ok := obj.(*types.Func)
				if !ok {
					return true
				}
				pos := fs.Position(fn.Pos())
				if !strings.Contains(pos.Filename, "/internal/") {
					return true
				}
				counts[fn]++
				declFile[fn] = pos.Filename
				return true
			})
		}
	})

	var res []info
	for fn, c := range counts {
		res = append(res, info{fn.FullName(), declFile[fn], c})
	}
	sort.Slice(res, func(i, j int) bool { return res[i].count > res[j].count })
	for i := 0; i < len(res) && i < 25; i++ {
		fp := res[i].pos
		if idx := strings.Index(fp, "/internal/"); idx >= 0 {
			fp = fp[idx+1:]
		}
		fmt.Printf("%4d  %s  [%s]\n", res[i].count, res[i].name, fp)
	}
}
EOF
